from pathlib import Path
W=Path(__file__).resolve().parent
html='''<!doctype html><html lang="zh"><meta charset="utf-8"><title>02 NE 连续支撑复核</title><style>body{background:#273340;color:white;font:16px sans-serif}button,select{font:inherit;margin:6px;padding:6px}.stage{display:flex;align-items:flex-start;gap:20px}#sprite{width:160px;height:160px;background:#273340}.contact{width:720px;height:auto}small{display:block;margin:12px 0}</style><h1>02 NE 连续支撑复核</h1><p>右16→07，左08→15；各两张一组。正常16×75ms=1200ms，慢放4800ms。</p><button id="play">暂停</button><button id="prev">上一帧</button><button id="next">下一帧</button><select id="speed"><option value="75">正常1200ms</option><option value="300">慢放4800ms</option></select><select id="size"><option value="160">游戏160px</option><option value="384">放大384px</option></select><select id="frame"></select><output id="label"></output><div class="stage"><img id="sprite"><img class="contact" src="eight-support-contact.jpg"></div><small>完整画布等比显示；无逐帧贴地或包围盒缩放。离线预览，客户端未接入。</small><script>let f=0,run=true,base=0,epoch=performance.now();const im=document.querySelector('#sprite'),lab=document.querySelector('#label'),speed=document.querySelector('#speed'),pick=document.querySelector('#frame');const src=Array.from({length:16},(_,i)=>'eight-support-selected-'+String(i+1).padStart(2,'0')+'.png');src.forEach((s,i)=>{let q=new Image;q.src=s;pick.add(new Option('帧 '+(i+1),String(i)))});function show(){im.src=src[f];lab.value='帧 '+(f+1)+' / 16';pick.value=String(f)}function tick(t){if(run){let n=(base+Math.floor((t-epoch)/Number(speed.value)))%16;if(n!==f){f=n;show()}}requestAnimationFrame(tick)}function pause(){run=false;document.querySelector('#play').textContent='播放'}document.querySelector('#play').onclick=()=>{run=!run;document.querySelector('#play').textContent=run?'暂停':'播放';base=f;epoch=performance.now()};document.querySelector('#prev').onclick=()=>{pause();f=(f+15)%16;show()};document.querySelector('#next').onclick=()=>{pause();f=(f+1)%16;show()};pick.onchange=()=>{pause();f=Number(pick.value);show()};speed.onchange=()=>{base=f;epoch=performance.now()};document.querySelector('#size').onchange=e=>{im.style.width=im.style.height=e.target.value+'px'};show();requestAnimationFrame(tick)</script></html>'''
(W/'eight-support-review.html').write_text(html,encoding='utf-8')
print('Preview updated')
